// SPDX-License-Identifier: Apache-2.0
// msfcore bootloader ROM: IMEM words 0..127 (128 x 16). Data sheet
// `tt_um_msf_bootrom_data.v` (initial block) is `include`d, generated by
// test/assembler.py from test/bootloader.s.
// STATUS: the DATA FILE IS STALE -- the last assembler run FAILED (arg
// errors in bootloader.s), so rom[] may hold outdated code. Regenerate.
// Read is registered (1-cycle latency) to match the SRAM macro timing.
// BUDGET: macro area, tracked under the IMEM ~1.5K line (isa.md 7.5).
// INTEGRATION: tt_um_msf.v selects by PC bit 7 (ROM <128, SRAM >=128);
// both feed imem_rd into tt_um_msf_ctrl's 2-stage fetch pipeline.
// NEXT: regenerate data; verify bootloader paths on RTL sim.
`default_nettype none

module tt_um_msf_bootrom (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [6:0] a,
    output wire [15:0] q
);
  reg [15:0] rom [0:127];
`include "tt_um_msf_bootrom_data.v"   // initial block: fills rom[0..127]
  reg [15:0] q_r;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) q_r <= 16'h0;
    else        q_r <= rom[a];
  end
  assign q = q_r;
endmodule
